/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesQuotationLine">_salesQuotationLine</param>
public void resetSalesQuotationLine(SalesQuotationLine _salesQuotationLine)
{
    newlyCreatedSalesQuotationLine.KCS_QLLVPosition          = _salesQuotationLine.KCS_QLLVPosition;
    newlyCreatedSalesQuotationLine.KCS_QLInternalPosition    = _salesQuotationLine.KCS_QLInternalPosition;
    newlyCreatedSalesQuotationLine.lineNum  = newlyCreatedSalesQuotationLine.buildLineNumFromLVPos();
    if (_salesQuotationLine.KCS_GAEBOZ)
    {
        newlyCreatedSalesQuotationLine.KCS_GAEBOZ   = _salesQuotationLine.KCS_GAEBOZ;
        newlyCreatedSalesQuotationLine.SalesQty     = _salesQuotationLine.SalesQty;
    }
    next  resetSalesQuotationLine(_salesQuotationLine);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_control">_control</param>
public void avaCreateCustQuotationJour(FormControl _control)
{
    Args args = new Args();
    args.record(SalesQuotationTable);
    args.caller(_control);

    new MenuFunction(menuItemActionStr(AVACreateQuotationJournal), MenuItemType::Action).run(args);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_control">_control</param>
public void avaCreateEmail(FormControl _control)
{
    CustQuotationJour           lastCustQuotationJour = CustQuotationJour::avaFindLatestQuotation(SalesQuotationTable.QuotationId);
    Args args = new Args();
    args.record(lastCustQuotationJour);
    args.caller(_control);

    new MenuFunction(menuItemActionStr(AVAERQuotationEmailCreation), MenuItemType::Action).run(args);
}
